CREATE OR REPLACE FUNCTION public.get_financeiro_saldos_periodo(p_start date, p_end date) RETURNS TABLE (banco_id text, entradas_periodo numeric, saidas_periodo numeric, entradas_acumuladas numeric, saidas_acumuladas numeric) LANGUAGE sql STABLE SET search_path = '' AS $$ SELECT banco_id, COALESCE(SUM(valor) FILTER (WHERE tipo = 'ENTRADA' AND data_competencia >= p_start), 0) AS entradas_periodo, COALESCE(SUM(valor) FILTER (WHERE tipo = 'SAIDA' AND data_competencia >= p_start), 0) AS saidas_periodo, COALESCE(SUM(valor) FILTER (WHERE tipo = 'ENTRADA'), 0) AS entradas_acumuladas, COALESCE(SUM(valor) FILTER (WHERE tipo = 'SAIDA'), 0) AS saidas_acumuladas FROM public.lancamentos_financeiros WHERE status = 'EFETIVADO' AND data_competencia < p_end GROUP BY banco_id $$